//! Resolving crate-qualified paths, such as `ferrowasp_input::rc_receiver`,
//! to the items they name, by parsing source with `syn`.
//!
//! Resolution follows what Rust code can name: modules in their own files or
//! inline, items, `use` re-exports including globs, and one further segment
//! after a type for an enum variant or a method. Items generated by macros
//! are invisible, and `#[cfg]` is ignored, so an item exists if any feature
//! set compiles it.

use std::cell::RefCell;
use std::collections::{BTreeMap, HashMap};
use std::path::{Path, PathBuf};
use std::rc::Rc;

use syn::{ImplItem, Item, TraitItem, UseTree};

use crate::workspace::Crate;

/// How deep re-exports may chain before resolution gives up.
const MAX_DEPTH: usize = 16;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Kind {
    Module,
    Function { test: bool },
    Type,
    Trait,
    Constant,
    Macro,
    Variant,
    Method { test: bool },
}

impl Kind {
    pub const fn is_test(self) -> bool {
        matches!(
            self,
            Self::Function { test: true } | Self::Method { test: true }
        )
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Resolved {
    pub crate_name: String,
    pub kind: Kind,
    pub file: PathBuf,
    /// Where the item is defined, `crate::module::Item`, after following
    /// re-exports.
    pub canonical: String,
}

/// A module: its crate, path from the crate root, the file holding its items,
/// and the directory its out-of-line child modules live in.
#[derive(Clone)]
pub(crate) struct Module {
    pub(crate) crate_name: String,
    pub(crate) path: Vec<String>,
    pub(crate) file: PathBuf,
    directory: PathBuf,
    pub(crate) items: Rc<Vec<Item>>,
}

/// What the longest resolvable prefix of a path reached.
pub(crate) struct Reached {
    pub(crate) crate_name: String,
    pub(crate) file: PathBuf,
    /// `None` for a module.
    pub(crate) kind: Option<Kind>,
    /// The last segment reached: a module, type or trait name.
    pub(crate) name: String,
    pub(crate) module: Option<Module>,
}

#[derive(Clone)]
enum Found {
    Module(Module),
    Leaf {
        kind: Kind,
        file: PathBuf,
        crate_name: String,
        /// The type or trait name, for a following variant or method.
        name: String,
        items: Rc<Vec<Item>>,
        /// The defining path inside the crate, ending in `name`.
        canonical: Vec<String>,
    },
}

/// A module's identity for caching: its file and path.
type ModuleKey = (PathBuf, Vec<String>);

pub struct Resolver<'a> {
    crates: &'a BTreeMap<String, Crate>,
    files: RefCell<HashMap<PathBuf, Rc<Vec<Item>>>>,
    /// Lookups already done, which never change within one run.
    lookups: RefCell<HashMap<(ModuleKey, String), Result<Found, String>>>,
}

impl<'a> Resolver<'a> {
    pub fn new(crates: &'a BTreeMap<String, Crate>) -> Self {
        Self {
            crates,
            files: RefCell::new(HashMap::new()),
            lookups: RefCell::new(HashMap::new()),
        }
    }

    pub fn resolve(&self, path: &str) -> Result<Resolved, String> {
        let segments: Vec<String> = path.split("::").map(str::to_owned).collect();
        if segments.iter().any(String::is_empty) {
            return Err(format!("{path}: malformed path"));
        }
        let root = self
            .crate_root(&segments[0])
            .ok_or_else(|| format!("{path}: no crate {} in the workspace", segments[0]))?;
        let found = self
            .walk(Found::Module(root), &segments[1..], 0)
            .map_err(|e| format!("{path}: {e}"))?;
        Ok(match found {
            Found::Module(module) => Resolved {
                canonical: qualified(&module.crate_name, &module.path),
                crate_name: module.crate_name,
                kind: Kind::Module,
                file: module.file,
            },
            Found::Leaf {
                kind,
                file,
                crate_name,
                canonical,
                ..
            } => Resolved {
                canonical: qualified(&crate_name, &canonical),
                crate_name,
                kind,
                file,
            },
        })
    }

    pub(crate) fn crate_root(&self, name: &str) -> Option<Module> {
        let found = self.crates.get(name)?;
        let lib = found.lib.as_ref()?;
        self.root_at(&found.name, lib).ok()
    }

    /// A crate root at `file`, such as a binary's `main.rs`, under a crate
    /// name of the caller's choosing.
    pub(crate) fn root_at(&self, crate_name: &str, file: &Path) -> Result<Module, String> {
        Ok(Module {
            crate_name: crate_name.to_owned(),
            path: Vec::new(),
            file: file.to_path_buf(),
            directory: file.parent().unwrap_or(Path::new(".")).to_path_buf(),
            items: self.parse(file)?,
        })
    }

    /// The modules a module declares, inline or in their own files,
    /// whatever their `#[cfg]`.
    pub(crate) fn submodules(&self, module: &Module) -> Vec<Result<Module, String>> {
        module
            .items
            .iter()
            .filter_map(|item| match item {
                Item::Mod(child) => Some(self.child(module, child)),
                _ => None,
            })
            .collect()
    }

    /// Resolves a path as written inside `module`, as far as it resolves:
    /// the longest prefix that names something, or `None` if not even the
    /// first segment does.
    pub(crate) fn reach(&self, module: &Module, path: &[String]) -> Option<Reached> {
        (1..=path.len()).rev().find_map(|length| {
            let found = self.follow(module, &path[..length], 0).ok()?;
            Some(match found {
                Found::Module(reached) => Reached {
                    crate_name: reached.crate_name.clone(),
                    file: reached.file.clone(),
                    kind: None,
                    name: reached.path.last().cloned().unwrap_or_default(),
                    module: Some(reached),
                },
                Found::Leaf {
                    kind,
                    file,
                    crate_name,
                    name,
                    ..
                } => Reached {
                    crate_name,
                    file,
                    kind: Some(kind),
                    name,
                    module: None,
                },
            })
        })
    }

    pub(crate) fn parse(&self, file: &Path) -> Result<Rc<Vec<Item>>, String> {
        if let Some(items) = self.files.borrow().get(file) {
            return Ok(Rc::clone(items));
        }
        let text = std::fs::read_to_string(file).map_err(|e| format!("{}: {e}", file.display()))?;
        let parsed = syn::parse_file(&text).map_err(|e| format!("{}: {e}", file.display()))?;
        let items = Rc::new(parsed.items);
        self.files
            .borrow_mut()
            .insert(file.to_path_buf(), Rc::clone(&items));
        Ok(items)
    }

    fn walk(&self, mut current: Found, segments: &[String], depth: usize) -> Result<Found, String> {
        for (index, segment) in segments.iter().enumerate() {
            current = match current {
                Found::Module(module) => self.lookup(&module, segment, depth)?,
                Found::Leaf {
                    kind,
                    name,
                    items,
                    file,
                    crate_name,
                    mut canonical,
                } => {
                    if index + 1 != segments.len() {
                        return Err(format!("{segment}: nothing can follow a member of {name}"));
                    }
                    let member = member(&items, kind, &name, segment)
                        .ok_or_else(|| format!("{name} has no variant or method {segment}"))?;
                    canonical.push(segment.clone());
                    Found::Leaf {
                        kind: member,
                        name: segment.clone(),
                        items,
                        file,
                        crate_name,
                        canonical,
                    }
                }
            };
        }
        Ok(current)
    }

    /// Finds `name` in a module: an item, a `use` that brings it in, or an
    /// item reached through a glob import.
    fn lookup(&self, module: &Module, name: &str, depth: usize) -> Result<Found, String> {
        let key = ((module.file.clone(), module.path.clone()), name.to_owned());
        if let Some(found) = self.lookups.borrow().get(&key) {
            return found.clone();
        }
        let found = self.lookup_uncached(module, name, depth);
        // A lookup cut short by depth is not cached, so a shallower one can
        // still succeed.
        if depth <= MAX_DEPTH {
            self.lookups.borrow_mut().insert(key, found.clone());
        }
        found
    }

    fn lookup_uncached(&self, module: &Module, name: &str, depth: usize) -> Result<Found, String> {
        if depth > MAX_DEPTH {
            return Err(format!("re-exports nest deeper than {MAX_DEPTH} levels"));
        }
        for item in module.items.iter() {
            if let Some(found) = self.declared(module, item, name)? {
                return Ok(found);
            }
        }
        let mut globs = Vec::new();
        for item in module.items.iter() {
            let Item::Use(declaration) = item else {
                continue;
            };
            let mut imports = Vec::new();
            flatten(&declaration.tree, &mut Vec::new(), &mut imports);
            for import in imports {
                match import {
                    Import::Named { path, visible } if visible == name => {
                        return self.follow(module, &path, depth + 1);
                    }
                    Import::Glob { path } => globs.push(path),
                    Import::Named { .. } => {}
                }
            }
        }
        for path in globs {
            if let Ok(Found::Module(target)) = self.follow(module, &path, depth + 1)
                && let Ok(found) = self.lookup(&target, name, depth + 1)
            {
                return Ok(found);
            }
        }
        let location = if module.path.is_empty() {
            module.crate_name.clone()
        } else {
            format!("{}::{}", module.crate_name, module.path.join("::"))
        };
        Err(format!("{location} has no item {name}"))
    }

    fn declared(&self, module: &Module, item: &Item, name: &str) -> Result<Option<Found>, String> {
        let leaf = |kind| {
            let mut canonical = module.path.clone();
            canonical.push(name.to_owned());
            Some(Found::Leaf {
                kind,
                file: module.file.clone(),
                crate_name: module.crate_name.clone(),
                name: name.to_owned(),
                items: Rc::clone(&module.items),
                canonical,
            })
        };
        Ok(match item {
            Item::Mod(child) if child.ident == name => {
                Some(Found::Module(self.child(module, child)?))
            }
            Item::Fn(function) if function.sig.ident == name => leaf(Kind::Function {
                test: is_test(&function.attrs),
            }),
            Item::Struct(s) if s.ident == name => leaf(Kind::Type),
            Item::Enum(e) if e.ident == name => leaf(Kind::Type),
            Item::Union(u) if u.ident == name => leaf(Kind::Type),
            Item::Type(t) if t.ident == name => leaf(Kind::Type),
            Item::Trait(t) if t.ident == name => leaf(Kind::Trait),
            Item::Const(c) if c.ident == name => leaf(Kind::Constant),
            Item::Static(s) if s.ident == name => leaf(Kind::Constant),
            Item::Macro(m) if m.ident.as_ref().is_some_and(|ident| ident == name) => {
                leaf(Kind::Macro)
            }
            _ => None,
        })
    }

    fn child(&self, parent: &Module, declaration: &syn::ItemMod) -> Result<Module, String> {
        let name = declaration.ident.to_string();
        let directory = parent.directory.join(&name);
        let mut path = parent.path.clone();
        path.push(name.clone());
        if let Some((_, items)) = &declaration.content {
            return Ok(Module {
                crate_name: parent.crate_name.clone(),
                path,
                file: parent.file.clone(),
                directory,
                items: Rc::new(items.clone()),
            });
        }
        let explicit = path_attribute(&declaration.attrs).map(|relative| {
            parent
                .file
                .parent()
                .unwrap_or(Path::new("."))
                .join(relative)
        });
        let candidates = match explicit {
            Some(file) => vec![file],
            None => vec![
                parent.directory.join(format!("{name}.rs")),
                directory.join("mod.rs"),
            ],
        };
        let file = candidates
            .into_iter()
            .find(|candidate| candidate.is_file())
            .ok_or_else(|| format!("module {name} has no source file"))?;
        let items = self.parse(&file)?;
        Ok(Module {
            crate_name: parent.crate_name.clone(),
            path,
            file,
            directory,
            items,
        })
    }

    /// Resolves a `use` path as written inside `module`.
    fn follow(&self, module: &Module, path: &[String], depth: usize) -> Result<Found, String> {
        let Some((first, rest)) = path.split_first() else {
            return Ok(Found::Module(module.clone()));
        };
        let start = match first.as_str() {
            "crate" => self
                .crate_root(&module.crate_name)
                .ok_or("crate root unreadable")?,
            "self" => module.clone(),
            "super" => self.parent(module)?,
            other => {
                if module.items.iter().any(|item| declares(item, other))
                    || self.crate_root(other).is_none()
                {
                    match self.lookup(module, other, depth)? {
                        Found::Module(found) => found,
                        leaf => {
                            return if rest.is_empty() {
                                Ok(leaf)
                            } else {
                                self.walk(leaf, rest, depth)
                            };
                        }
                    }
                } else {
                    self.crate_root(other).ok_or("crate root unreadable")?
                }
            }
        };
        self.walk(Found::Module(start), rest, depth)
    }

    fn parent(&self, module: &Module) -> Result<Module, String> {
        let Some((_, ancestors)) = module.path.split_last() else {
            return Err("super:: at a crate root".to_owned());
        };
        let root = self
            .crate_root(&module.crate_name)
            .ok_or("crate root unreadable")?;
        match self.walk(Found::Module(root), ancestors, 0)? {
            Found::Module(parent) => Ok(parent),
            Found::Leaf { .. } => Err("super:: is not a module".to_owned()),
        }
    }
}

fn qualified(crate_name: &str, path: &[String]) -> String {
    if path.is_empty() {
        crate_name.to_owned()
    } else {
        format!("{crate_name}::{}", path.join("::"))
    }
}

fn declares(item: &Item, name: &str) -> bool {
    match item {
        Item::Mod(m) => m.ident == name,
        Item::Use(declaration) => {
            let mut imports = Vec::new();
            flatten(&declaration.tree, &mut Vec::new(), &mut imports);
            imports
                .iter()
                .any(|import| matches!(import, Import::Named { visible, .. } if visible == name))
        }
        _ => false,
    }
}

/// A variant of an enum, or a method of a type or trait, named `member`.
fn member(items: &[Item], kind: Kind, owner: &str, member: &str) -> Option<Kind> {
    for item in items {
        match item {
            Item::Enum(e) if kind == Kind::Type && e.ident == owner => {
                if e.variants.iter().any(|variant| variant.ident == member) {
                    return Some(Kind::Variant);
                }
            }
            Item::Trait(t) if kind == Kind::Trait && t.ident == owner => {
                for trait_item in &t.items {
                    if let TraitItem::Fn(function) = trait_item
                        && function.sig.ident == member
                    {
                        return Some(Kind::Method { test: false });
                    }
                }
            }
            Item::Impl(block) if kind == Kind::Type && self_type_is(&block.self_ty, owner) => {
                for impl_item in &block.items {
                    if let ImplItem::Fn(function) = impl_item
                        && function.sig.ident == member
                    {
                        return Some(Kind::Method {
                            test: is_test(&function.attrs),
                        });
                    }
                }
            }
            Item::Mod(child) => {
                if let Some((_, inner)) = &child.content
                    && let Some(found) = self::member(inner, kind, owner, member)
                {
                    return Some(found);
                }
            }
            _ => {}
        }
    }
    None
}

pub(crate) fn self_type_is(ty: &syn::Type, name: &str) -> bool {
    match ty {
        syn::Type::Path(path) => path
            .path
            .segments
            .last()
            .is_some_and(|segment| segment.ident == name),
        _ => false,
    }
}

/// `#[test]`, or any attribute whose path ends in `test`.
fn is_test(attributes: &[syn::Attribute]) -> bool {
    attributes.iter().any(|attribute| {
        attribute
            .path()
            .segments
            .last()
            .is_some_and(|segment| segment.ident == "test")
    })
}

fn path_attribute(attributes: &[syn::Attribute]) -> Option<String> {
    attributes.iter().find_map(|attribute| {
        if !attribute.path().is_ident("path") {
            return None;
        }
        let syn::Meta::NameValue(value) = &attribute.meta else {
            return None;
        };
        match &value.value {
            syn::Expr::Lit(syn::ExprLit {
                lit: syn::Lit::Str(literal),
                ..
            }) => Some(literal.value()),
            _ => None,
        }
    })
}

pub(crate) enum Import {
    Named { path: Vec<String>, visible: String },
    Glob { path: Vec<String> },
}

pub(crate) fn flatten(tree: &UseTree, prefix: &mut Vec<String>, out: &mut Vec<Import>) {
    match tree {
        UseTree::Path(path) => {
            prefix.push(path.ident.to_string());
            flatten(&path.tree, prefix, out);
            prefix.pop();
        }
        UseTree::Name(name) => {
            let ident = name.ident.to_string();
            if ident == "self" {
                if let Some(last) = prefix.last() {
                    out.push(Import::Named {
                        path: prefix.clone(),
                        visible: last.clone(),
                    });
                }
            } else {
                let mut path = prefix.clone();
                path.push(ident.clone());
                out.push(Import::Named {
                    path,
                    visible: ident,
                });
            }
        }
        UseTree::Rename(rename) => {
            let ident = rename.ident.to_string();
            let path = if ident == "self" {
                prefix.clone()
            } else {
                let mut path = prefix.clone();
                path.push(ident);
                path
            };
            out.push(Import::Named {
                path,
                visible: rename.rename.to_string(),
            });
        }
        UseTree::Glob(_) => out.push(Import::Glob {
            path: prefix.clone(),
        }),
        UseTree::Group(group) => {
            for item in &group.items {
                flatten(item, prefix, out);
            }
        }
    }
}
